"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/kbd.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type KbdProps = ComponentPropsWithRef<"kbd">;

export function Kbd({ className, ...props }: KbdProps) {
  return <kbd className={cn("whatiuse-kbd", className)} {...props} />;
}

export type KbdGroupProps = ComponentPropsWithRef<"span">;

export function KbdGroup({ className, ...props }: KbdGroupProps) {
  return <span className={cn("whatiuse-kbd-group", className)} {...props} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-kbd-group { display: inline-flex; align-items: center; gap: 3px; color: var(--whatiuse-fg-muted); font-size: 11px; white-space: nowrap; }

.whatiuse-kbd {
  display: inline-flex;
  min-width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border: 0;
  border-radius: 4px;
  background: var(--whatiuse-bg-subtle);
  box-shadow: inset 0 0 0 1px var(--whatiuse-separator), 0 1px 0 color-mix(in oklch, var(--whatiuse-fg-default) 8%, transparent);
  color: var(--whatiuse-fg-muted);
  font-family: var(--whatiuse-font-code);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}
}
